{"content":"import unittest

from beer_song import recite


class BeerSongTest(unittest.TestCase):
    def test_default_single_verse(self):
        self.assertEqual(recite(99), [
            "99 bottles of beer on the wall, 99 bottles of beer.",
            "Take one down and pass it around, 98 bottles of beer on the wall.",
        ])

    def test_final_three_verses(self):
        self.assertEqual(recite(2, 3), [
            "2 bottles of beer on the wall, 2 bottles of beer.",
            "Take one down and pass it around, 1 bottle of beer on the wall.",
            "",
            "1 bottle of beer on the wall, 1 bottle of beer.",
            "Take it down and pass it around, no more bottles of beer on the wall.",
            "",
            "No more bottles of beer on the wall, no more bottles of beer.",
            "Go to the store and buy some more, 99 bottles of beer on the wall.",
        ])

    def test_zero_verses(self):
        self.assertEqual(recite(99, 0), [])

    def test_full_song(self):
        song = recite(99, 100)
        self.assertEqual(len(song), 299)
        self.assertEqual(song[-8:], recite(2, 3))
        for index, number in enumerate(range(99, 2, -1)):
            offset = index * 3
            self.assertEqual(song[offset:offset + 3], [
                f"{number} bottles of beer on the wall, {number} bottles of beer.",
                f"Take one down and pass it around, {number - 1} bottles of beer on the wall.",
                "",
            ])


if __name__ == "__main__":
    unittest.main()
